statement.raw_tex:
\begin{theorem}[convergence rate II with constant stepsizes]\label{thm:rate-const2}
	Under Assumptions~\ref{assump-obj} through \ref{assump-sgd}, let $\{\vx^k\}$ be the iterate sequence from Algorithm~\ref{alg:prox-storm} with $ \eta_k =\frac{\eta}{L \sqrt[3]{K}}$ and $\{\beta_k\}$ set by \eqref{eq:beta-def}, 
	where $\eta \le \frac{1}{4}$ is a positive number. If $\tau$ is selected from $\{0,1,\ldots,K-1\}$ uniformly at random, then
	\begin{equation}\label{eq:rate-grad-const2}
		\EE[\|\bar\vg^\tau\|^2] \le \frac{1}{K^{\frac{2}{3}}} 
		\left(	\frac{12 L}{\eta}\big[\Phi(\vx^0)-\Phi^*\big] + \Big( 2^{-1/3}+\frac{1}{6}2^{1/3}+\frac{1}{36}\Big) \frac{8}{\sqrt[3]{K}} \frac{\sigma^2}{ m_0} +  \frac{12\sigma^2 L}{ \eta m_0}
		+ \frac{ 32}{(1-2^{-2/3})^2} \frac{\sigma^2}{m}\right).
	\end{equation}
\end{theorem}

