\begin{lemma}[one-iteration progress]\label{lem:obj-diff}
Let $\{\vx^k\}$ be generated from Algorithm~\ref{alg:prox-storm}. If $F$ is $L$-smooth, then
$$\Phi(\vx^{k+1})-\Phi(\vx^k) \le \frac{\eta_k}{2}(2-\eta_k L)\|\ve^k\|^2 - \frac{\eta_k}{4}(1-\eta_k L)\|\bar\vg^k\|^2,\, \forall\, k\ge 1,$$
where $\bar\vg^k$ is defined in \eqref{eq:vg-vgbar}.
\end{lemma}

\begin{proof}
By the $L$-smoothness of $F$ and the definition of $\vg^k$ in \eqref{eq:vg-vgbar}, we have
\begin{equation}\label{eq:lip-F-ineq}
F(\vx^{k+1})-F(\vx^k)\le \langle \nabla F(\vx^k), \vx^{k+1}-\vx^k\rangle + \frac{L}{2}\|\vx^{k+1}-\vx^k\|^2 = -\eta_k\langle \nabla F(\vx^k), \vg^k\rangle + \frac{\eta_k^2L}{2}\|\vg^k\|^2.
\end{equation}
Using the definition of $\ve^k$ in \eqref{eq:error-grad} and the inequality in \eqref{eq:lem1-lan}, we have 
$$-\langle \nabla F(\vx^k), \vg^k\rangle = \langle \ve^k, \vg^k\rangle - \langle \vd^k, \vg^k\rangle \le \langle \ve^k, \vg^k\rangle - \|\vg^k\|^2 + \frac{1}{\eta_k}\big(r(\vx^k)-r(\vx^{k+1})\big).$$
Plugging the above inequality into \eqref{eq:lip-F-ineq} and rearranging terms give
$$\Phi(\vx^{k+1})-\Phi(\vx^k) \le \eta_k\langle \ve^k, \vg^k\rangle - \eta_k \|\vg^k\|^2+ \frac{\eta_k^2L}{2}\|\vg^k\|^2.$$
By the Cauchy-Schwartz inequality, it holds $\eta_k\langle \ve^k, \vg^k\rangle \le \frac{\eta_k}{2}\|\ve^k\|^2 + \frac{\eta_k}{2}\|\vg^k\|^2$, which together with the above inequality implies
\begin{equation}\label{eq:chg-obj-0}
\Phi(\vx^{k+1})-\Phi(\vx^k) \le \frac{\eta_k}{2}\|\ve^k\|^2 - \frac{\eta_k}{2}(1-\eta_k L)\|\vg^k\|^2.
\end{equation}
From \eqref{eq:nonexp-P} and the definitions of $\vg^k$ and $\bar\vg^k$ in \eqref{eq:vg-vgbar}, it follows
\begin{equation}\label{eq:tri-g}
-\|\vg^k\|^2 \le -\frac{1}{2}\|\bar\vg^k\|^2 + \|\vg^k-\bar\vg^k\|^2\le -\frac{1}{2}\|\bar\vg^k\|^2 + \|\vd^k -\nabla F(\vx^k)\|^2 = -\frac{1}{2}\|\bar\vg^k\|^2 + \|\ve^k\|^2.
\end{equation}
Now plug the above inequality into \eqref{eq:chg-obj-0} to give the desired result.
\end{proof}

\begin{lemma}[recursive bound on gradient error]\label{lem:bd-ek}
Under Assumptions~\ref{assump-smooth} and \ref{assump-sgd}, it holds %for each $k\ge 0$ that
$$\EE\big[\|\ve^{k+1}\|^2\big] \le \frac{2\beta_k^2\sigma^2}{m} + \frac{4(1-\beta_k)^2\eta_{k}^2 L^2}{m} \EE\big[\|\bar\vg^{k}\|^2\big] + (1-\beta_k)^2\left(\textstyle 1+\frac{4\eta_{k}^2 L^2}{m}\right)\EE\big[\|\ve^{k}\|^2\big], \forall\, k\ge0,$$
where $\bar\vg^k$ and $\ve^k$ are defined in \eqref{eq:vg-vgbar} and \eqref{eq:error-grad}.
\end{lemma}

\begin{proof}
First, notice $\EE_{B_{k+1}}[\langle \vv^{k+1}, \ve^{k}\rangle] = \langle\nabla F(\vx^{k+1}), \ve^{k}\rangle$ and $\EE_{B_{k+1}}[\langle \vu^{k+1}, \ve^{k}\rangle] = \langle\nabla F(\vx^{k}), \ve^{k}\rangle$, and thus
\begin{equation}\label{eq:crs-term0}
\EE_{B_{k+1}}[\langle \vv^{k+1} - \nabla F(\vx^{k+1}), \ve^{k}\rangle] = 0,\quad \EE_{B_{k+1}}[\langle \vu^{k+1} - \nabla F(\vx^{k}), \ve^{k}\rangle] = 0.
\end{equation}
Hence, by writing $\ve^{k+1} = \vv^{k+1} - \nabla F(\vx^{k+1}) + (1-\beta_k)(\nabla F(\vx^{k})- \vu^{k+1})+(1-\beta_k)\ve^{k}$, we have
\begin{equation}\label{eq:one-step-e}
\EE_{B_{k+1}}\big[\|\ve^{k+1}\|^2\big] = \EE_{B_{k+1}}\big[\|\vv^{k+1} - \nabla F(\vx^{k+1}) + (1-\beta_k)(\nabla F(\vx^{k})- \vu^{k+1})\|^2\big] + (1-\beta_k)^2\|\ve^{k}\|^2.
\end{equation}
By the Young's inequality, it holds
\begin{align}\label{eq:step2}
&~\|\vv^{k+1} - \nabla F(\vx^{k+1}) + (1-\beta_k)(\nabla F(\vx^{k})- \vu^{k+1})\|^2 \cr
= &~ \big\|\beta_k\big(\vv^{k+1} - \nabla F(\vx^{k+1})\big) + (1-\beta_k)\big(\vv^{k+1} - \nabla F(\vx^{k+1}) + \nabla F(\vx^{k})- \vu^{k+1}\big)\big\|^2\cr
\le &~ 2\beta_k^2\|\vv^{k+1} - \nabla F(\vx^{k+1})\|^2 + 2(1-\beta_k)^2\|\vv^{k+1} - \nabla F(\vx^{k+1}) + \nabla F(\vx^{k})- \vu^{k+1}\|^2.
\end{align}
From the definition of $\vv^{k+1}$ and $ \vu^{k+1}$ in \eqref{eq:def-v-u-k}, we have 
\begin{align}\label{eq:step23}
 	&~\EE_{B_{k+1}}\big[\|\vv^{k+1} - \nabla F(\vx^{k+1}) + \nabla F(\vx^{k})- \vu^{k+1}\|^2\big] \cr 
 	=&~\frac{1}{m^2}\EE_{B_{k+1}}\left\| \sum_{\xi\in B_{k+1}}\left(\nabla f(\vx^{k+1};\xi)-\nabla f(\vx^{k};\xi)  - \nabla F(\vx^{k+1})+\nabla F(\vx^{k})\right) \right\|^2 	 \cr
 	=&~\frac{1}{m^2}\sum_{j=1}^m\EE_{\xi_j^{k+1}}\left\| \nabla f(\vx^{k+1};\xi_j^{k+1})-\nabla f(\vx^{k};\xi_j^{k+1})  - \nabla F(\vx^{k+1})+\nabla F(\vx^{k})  \right\|^2 	 \cr
 	\le&~\frac{1}{m^2}\sum_{j=1}^m\EE_{\xi_j^{k+1}}\left\| \nabla f(\vx^{k+1};\xi_j^{k+1})-\nabla f(\vx^{k};\xi_j^{k+1}) \right\|^2 	 \cr	
 	\le&~\frac{L^2}{m}\|\vx^{k+1}-\vx^{k}\|^2,
\end{align}
where the second equality holds because of the i.i.d. samples in $B_{k+1}$ and the zero mean of the random vector $\nabla f(\vx^{k+1};\xi_j^{k+1})-\nabla f(\vx^{k};\xi_j^{k+1})  - \nabla F(\vx^{k+1})+\nabla F(\vx^{k}) $ resulted from unbiasedness in Assumption~\ref{assump-sgd}, 
the first inequality is due to the fact that the variance of a random vector is upper-bounded by its second moment, and the last inequality follows from Assumption~\ref{assump-smooth}.

Now, take conditional expectation on both sides of \eqref{eq:step2}, use \eqref{eq:step23}, and substitute it into \eqref{eq:one-step-e}. We have
$$\EE_{B_{k+1}}\big[\|\ve^{k+1}\|^2\big] \le (1-\beta_k)^2\|\ve^{k}\|^2 +2\beta_k^2\EE_{B_{k+1}} \big[\|\vv^{k+1} - \nabla F(\vx^{k+1})\|^2\big] + \frac{2(1-\beta_k)^2 L^2}{m} \EE_{B_{k+1}}\big[\|\vx^{k+1}-\vx^{k}\|^2\big] .$$
Taking a full expectation over the above inequality and using  Assumption~\ref{assump-sgd}, we have
	\begin{align}\label{eq:step32}
		\EE\big[\|\ve^{k+1}\|^2\big] \le &~ (1-\beta_k)^2\EE\big[\|\ve^{k}\|^2\big]+ \frac{2\beta_k^2\sigma^2}{m} + \frac{2(1-\beta_k)^2 L^2}{m} \EE\big[\|\vx^{k+1}-\vx^{k}\|^2\big]\cr
		= & ~ (1-\beta_k)^2\EE\big[\|\ve^{k}\|^2\big]+ \frac{2\beta_k^2\sigma^2}{m} + \frac{2(1-\beta_k)^2 \eta_k^2 L^2}{m} \EE\big[\|\vg^{k}\|^2\big],
	\end{align}
where we have used	$\vx^{k+1}-\vx^{k} = -\eta_{k} \vg^{k}$ in the equality.


By similar arguments as those in \eqref{eq:tri-g}, it holds
$$\|\vg^{k}\|^2 \le 2\|\bar\vg^{k}\|^2 + 2\|\vg^{k}-\bar\vg^{k}\|^2\le 2\|\bar\vg^{k}\|^2  + 2\|\ve^{k}\|^2.$$
%Now notice $\vx^{k+1}-\vx^{k} = -\eta_{k} \vg^{k}$ and 
Plugging the above inequality into \eqref{eq:step32}, we obtain the desired result.
\end{proof}

\begin{theorem}\label{thm:main}
	Under Assumptions~\ref{assump-obj} through \ref{assump-sgd}, let $\{\vx^k\}$ be the iterate sequence from Algorithm~\ref{alg:prox-storm}. Suppose there are constants $A$ and $B$ such that the parameters $\{\eta_k\}$ and $\{\beta_k\}$ satisfying the conditions:
	\begin{equation}\label{eq:cond-eta-beta1}
		2\eta_k L+ \frac{4 L^2}{m} \frac{\eta_{k}}{\Gamma_{k} } \sum_{j=k+1}^{K-1}\eta_j\Gamma_{j} \le 1, \,\forall\, k=0,\ldots,K-1,
	\end{equation}
	\begin{equation}\label{eq:cond-eta-beta2}
\sum_{k=1}^{K-1}\eta_k\Gamma_{k}\le A,~\text{and}~\sum_{k=1}^{K-1}\eta_k\Gamma_{k}\sum_{j=0}^{k-1}\frac{\beta_j^2}{\Gamma_{j+1} }\le B,
\end{equation}
where $K$ is the maximum number of iterations in Algorithm~\ref{alg:prox-storm}. 
	Let $\{\bar\vg^k\}$ be defined in \eqref{eq:vg-vgbar}. Then	
	\begin{equation}\label{eq:mainthm}
		\sum_{k=0}^{K-1} \eta_k \EE\big[\|\bar\vg^{k}\|^2\big] 
		\le	12\big[\Phi(\vx^0)-\Phi^*\big] +4(2A+3)\frac{\sigma^2}{ m_0}+ 16B\frac{\sigma^2}{m} .
	\end{equation}	
\end{theorem}

\begin{lemma}\label{lem:keylem}
	Let 
	\begin{equation}\label{eq:beta-def}
		\beta_{k}=3\big[(k+3)^{1/3}-(k+2)^{1/3}\big],\quad k\ge 0,
	\end{equation}
Then we  have %the following bounds,
\begin{equation}\label{eq:keylem1}
	\sum_{j=k+1}^{K-1}\frac{\Gamma_{j}}{\Gamma_{k}} \le \frac{1}{2}(k+2)^{2/3}+\frac{1}{6}(k+2)^{1/3}+\frac{1}{36}. 
\end{equation}
%and 
%\begin{equation}\label{eq:keylem2}
%	\sum_{j=k+1}^{K-1}(j+2)^{-1/3}\frac{\Gamma_{j}}{\Gamma_{k}} 
%	\le \frac{1}{2}  (k+2)^{1/3}+\frac{1}{12}.
%\end{equation}
\end{lemma}

\begin{proof}	
	By the fact $a^3-b^3 = (a-b)(a^2+ab+b^2)$, we have %We begin by realizing that 
	\begin{equation}\label{eq:beta-bound}
		\beta_{k}=3\big[(k+3)^{1/3}-(k+2)^{1/3}\big]=
		\frac{3}{(k+3)^{2/3}+(k+3)^{1/3}(k+2)^{1/3}+(k+2)^{2/3}}.
	\end{equation}
	Hence, $\beta_{k}\in \big[(k+3)^{-2/3},(k+2)^{-2/3}\big]$ for all $k\ge 0$, and it is a decreasing sequence. In addition,
	%We then establish the trick for bounding $\Gamma_{j}/\Gamma_{k}$: for all $j>k\ge 0,$ 
by the definition of $\Gamma_k$ and $\beta_k$, it holds for all $j>k\ge 0$ that
\begin{equation}\label{eq:keystring}
	\frac{\Gamma_{j}}{\Gamma_{k}} 
	= \frac{\prod_{l=0}^{j-1}(1-\beta_l)^2}{\prod_{l=0}^{k-1}(1-\beta_l)^2}  = \prod_{l=k}^{j-1}(1-\beta_l)^2
	\le  e^{-2\sum_{l=k}^{j-1}\beta_l}
	=  e^{-6\big[(j+2)^{1/3}-(k+2)^{1/3}\big]},
\end{equation}	
where the inequality holds because $0\le 1+x\le e^x, \forall\, x\ge -1$. Therefore we have that for any $k\ge 0,$
\begin{equation}\label{eq:key-beta-ineq1}
\sum_{j=k+1}^{K-1}\frac{\Gamma_{j}}{\Gamma_{k}} 
%=	\sum_{j=k+1}^{K-1} \prod_{l=k}^{j-1}(1-\beta_l)^2
\le %\sum_{j=k+1}^{K-1} e^{-2\sum_{l=k}^{j-1}\beta_l}
 \sum_{j=k+1}^{K-1} e^{-6\big[(j+2)^{1/3}-(k+2)^{1/3}\big]}
= e^{6(k+2)^{1/3}}\sum_{j=k+1}^{K-1} e^{-6 (j+2)^{1/3} }.
\end{equation}
	Since $e^{-6x^{1/3}}$ is a decreasing function and has an anti-derivative $-\frac{1}{36} e^{-6x^{1/3}} (18x^{2/3}+6x^{1/3}+1)$, we have %$\int e^{-6x^{1/3}}dx=-\frac{1}{36} e^{-6x^{1/3}} (18x^{2/3}+6x^{1/3}+1)+C,$ 
	\begin{equation}\label{eq:key-beta-ineq2}
\sum_{j=k+1}^{K-1} e^{-6 (j+2)^{1/3} }
\le \int_{k+2}^{K+1} e^{-6x^{1/3}}dx
\le \frac{1}{36}  e^{-6(k+2)^{1/3}} (18(k+2)^{2/3}+6(k+2)^{1/3}+1) .
	\end{equation}
	Substituting \eqref{eq:key-beta-ineq2} into \eqref{eq:key-beta-ineq1} gives \eqref{eq:keylem1} and completes the proof.
\end{proof}

